    // Story 1.5 Round 2 — tenant stubs guarded by the canonical
    // Platform\Authz route.permission middleware. Capability mapping
    // lives in config/route_permissions.php; both role and plan gates
    // are evaluated through a single pipeline.
    Route::redirect('/automations', '/automations/dashboard')
        ->name('automations.legacy');

    Route::get('/events', EventList::class)
        ->name('events.index');

    // Account settings
    Route::get('/account/personal', $workspacePage('account.personal'))->name('account.personal');
    Route::get('/account/security', $workspacePage('account.security'))->name('account.security');
    Route::get('/account/sessions', $workspacePage('account.sessions'))->name('account.sessions');
    Route::get('/account/notifications', $workspacePage('account.notifications'))->name('account.notifications');
});

// Authenticated tenant routes with permission checking.
Route::middleware(array_filter([
    'auth:web',
    config('jetstream.auth_session'),
    'verified',
    'workspace.active',
]))->group(function () {
    // Dashboard
    Route::get('/dashboard', function (
        EventService $eventService,
        SubscriptionLockService $subscriptions,
        PreRenewalWarningService $preRenewalWarnings,
    ) {
        $user = authUser();
        if (
            $user instanceof User &&
            $user->shouldBypassTeamScope()
        ) {
            return redirect()->route('admin.dashboard');
        }

        // R5: Redirect workspace-less users to wizard instead of showing 403/empty dashboard
        $team = $user instanceof User ? $user->currentTeam : null;
        if (! $team) {
            return redirect()->route('workspace.create');
        }

        // R3: Pass service-backed data from route closure — no Eloquent queries in Blade.
        return view('dashboard', [
            'dashboardEvents' => $eventService->getDashboardEventsForTeam($team),
            'dashboardEventCount' => $eventService->countEventsForTeam($team),
            'dashboardUpcomingEventCount' => $eventService->countUpcomingEventsForTeam($team),
            'team' => $team,
            'dashboardCurrentPlan' => $subscriptions->getCurrentPlan($team),
            'dashboardShowPreRenewalWarning' => $preRenewalWarnings->hasApproachingRenewalWithoutCard($team),
        ]);
    })->name('user.dashboard');

    // Legacy Jetstream team URL kept as a compatibility redirect to the
    // canonical workspace settings surface.
    Route::get('/teams/{team}', function (Team $team) {
        abort_unless((int) authUser()?->current_team_id === (int) $team->getKey(), 404);

        return redirect()->route('workspace.settings');
    })->name('teams.show');

});

// Admin routes kept outside the tenant workspace guard so suspended-workspace
// members with system-admin access can still reach the platform ops surfaces.
Route::middleware(array_filter([
    'auth:web',
    config('jetstream.auth_session'),
    'verified',
]))->prefix('admin')
    ->name('admin.')
    ->group(function () {
        // User Impersonation routes stay app-level and are out of the
        // SuperAdmin module scope for story 1-11a.
        Route::post('/impersonate/{user}', [
            UserImpersonationController::class,
            'start',
        ])->middleware('throttle:10,1')->name('impersonate.start');

        Route::get('/impersonate/status', [
            UserImpersonationController::class,
            'status',
        ])->name('impersonate.status');

